// Решаем, нужна ли новая тема, и готовим список каналов
const rows = $input.all().map(i => i.json).filter(r => r.id !== undefined);
const approved = rows.filter(r => r.status === 'approved').length;
const freshDrafts = rows.filter(r =>
  r.status === 'draft' && Date.now() - new Date(r.createdAt).getTime() < 20 * 3600e3
).length;

// Ручной тест и кнопка «Другая тема» запускают генерацию всегда
const forced = $('Тест вручную').isExecuted || $('При регенерации').isExecuted;
if (!forced && (approved >= 3 || freshDrafts > 0)) return []; // очередь полная или ждём апрув

const used_urls = rows.map(r => r.source_url).filter(Boolean);
const channels = String($('Config').first().json.channels)
  .split(',')
  .map(s => s.trim().replace(/^https?:\/\/t\.me\//, '').replace(/^@/, ''))
  .filter(Boolean);

return channels.map(channel => ({ json: { channel, used_urls } }));

// Разбираем веб-превью публичных каналов t.me/s/<канал>
const used = new Set($('Проверка очереди').first().json.used_urls || []);
const MAX_AGE = 48 * 3600e3;

const decode = s => s
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .trim();

const posts = [];
for (const item of $input.all()) {
  const html = item.json.data || '';
  const blocks = String(html).split('tgme_widget_message_wrap').slice(1);
  for (const b of blocks) {
    const post = (b.match(/data-post="([^"]+)"/) || [])[1];
    const body = (b.match(/tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/) || [])[1];
    const dt = (b.match(/<time[^>]*datetime="([^"]+)"/) || [])[1];
    if (!post || !body || !dt) continue;
    const url = 'https://t.me/' + post;
    if (used.has(url)) continue;
    if (Date.now() - new Date(dt).getTime() > MAX_AGE) continue;
    const text = decode(body);
    if (text.length < 120) continue; // отсекаем короткий мусор
    posts.push({ url, date: dt, text: text.slice(0, 1200) });
  }
}

posts.sort((a, b) => new Date(b.date) - new Date(a.date));
const top = posts.slice(0, 30);
if (!top.length) return []; // нет свежих постов — ничего не генерируем

const digest = top.map((p, i) => `[${i + 1}] ${p.url}\n${p.text}`).join('\n\n---\n\n');
return [{ json: { digest, count: top.length } }];

// Достаём JSON из ответа нейросети и готовим 3 строки для таблицы Posts
let raw = String($input.first().json.text || '');
raw = raw.replace(/```json|```/g, '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start < 0 || end < 0) throw new Error('Нейросеть не вернула JSON: ' + raw.slice(0, 300));
const data = JSON.parse(raw.slice(start, end + 1));

const langs = ['uk', 'ru', 'en'];
for (const l of langs) {
  if (!data[l]) throw new Error('В ответе нет версии ' + l);
}

const topic_id = 't' + Date.now().toString(36);
return langs.map((lang, i) => ({
  json: {
    topic_id,
    lang,
    seq: i + 1,
    text: String(data[lang]).trim().slice(0, 2900), // лимит поста LinkedIn — 3000 символов
    status: 'draft',
    source_url: data.source_url || '',
  },
}));

// Отправляем черновик в Telegram: 3 сообщения, кнопки на последнем
const cfg = $('Config').first().json;
const rows = $('Разбор ответа ИИ').all().map(i => i.json);
const tid = rows[0].topic_id;
const flag = { uk: '🇺🇦 UA', ru: '🇷🇺 RU', en: '🇬🇧 EN' };

const send = body => this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${cfg.bot_token}/sendMessage`,
  json: true,
  body: { chat_id: cfg.telegram_chat_id, disable_web_page_preview: true, ...body },
});

await send({ text: `📝 Новый черновик ${tid}\nИсточник: ${rows[0].source_url || '—'}` });
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  const body = { text: `${flag[r.lang]}\n\n${r.text}`.slice(0, 4000) };
  if (i === rows.length - 1) {
    body.reply_markup = {
      inline_keyboard: [[
        { text: '✅ Опубликовать', callback_data: `approve:${tid}` },
        { text: '🔄 Другая тема', callback_data: `regen:${tid}` },
        { text: '❌ Пропустить', callback_data: `skip:${tid}` },
      ]],
    };
  }
  await send(body);
}
return [{ json: { sent: true, topic_id: tid } }];
